import http from 'k6/http';
import { check } from 'k6';
import { Counter } from 'k6/metrics';

const createdCount = new Counter('status_201_created');
const conflictCount = new Counter('status_409_conflict');
const serverErrorCount = new Counter('status_500_error');

export const options = {
  scenarios: {
    race_condition: {
      executor: 'shared-iterations',
      vus: 2000,
      iterations: 2000,
      maxDuration: '30s',
    },
  },
};

export default function () {
  const payload = JSON.stringify({
    email: 'race-condition-target@example.com',
    password: 'Password123!',
  });

  const params = {
    headers: { 'Content-Type': 'application/json' },
  };

  const res = http.post('http://localhost:3000/register', payload, params);

  if (res.status === 201) {
    createdCount.add(1);
  } else if (res.status === 409) {
    conflictCount.add(1);
  } else if (res.status >= 500) {
    serverErrorCount.add(1);
  }

  check(res, {
    'is 201 or 409 (no 500)': (r) => r.status === 201 || r.status === 409,
  });
}

