import http from 'k6/http';
import { check, sleep } from 'k6';

export const options = {
  scenarios: {
    mixed_traffic: {
      executor: 'ramping-vus',
      startVUs: 0,
      stages: [
        { duration: '1m', target: 2000 },
        { duration: '3m', target: 5000 },
        { duration: '1m', target: 0 },
      ],
    },
  },
  thresholds: {
    'http_req_duration{endpoint:products}': ['p(95)<300'],
    'http_req_duration{endpoint:orders}': ['p(95)<800'],
  },
};

export default function () {
  const rand = Math.random() * 100;

  if (rand < 70) {
    // 70% Products
    const res = http.get('http://localhost:3000/products', { tags: { endpoint: 'products' } });
    check(res, { 'products 200': (r) => r.status === 200 });
  } else if (rand < 90) {
    // 20% Profile
    const res = http.get('http://localhost:3000/profile', {
      headers: { Authorization: 'Bearer mock-jwt-token' },
      tags: { endpoint: 'profile' },
    });
    check(res, { 'profile 200': (r) => r.status === 200 });
  } else if (rand < 95) {
    // 5% Orders
    const res = http.post('http://localhost:3000/orders', JSON.stringify({ productId: 1, qty: 1 }), {
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer mock-jwt-token' },
      tags: { endpoint: 'orders' },
    });
    check(res, { 'order 201': (r) => r.status === 201 });
  } else {
    // 5% Login
    const res = http.post('http://localhost:3000/login', JSON.stringify({ email: 'user@test.com', password: '123' }), {
      headers: { 'Content-Type': 'application/json' },
      tags: { endpoint: 'login' },
    });
    check(res, { 'login 200': (r) => r.status === 200 });
  }

  sleep(0.5);
}

