export const options = {
  scenarios: {
    production_load: {
      executor: 'ramping-vus',
      stages: [
        { duration: '2m', target: 2000 },
        { duration: '3m', target: 10000 }, // Peak production load
        { duration: '3m', target: 10000 },
        { duration: '2m', target: 0 },
      ],
    },
  },
  thresholds: {
